  "is_criterion": true,
  "kind": "exclusion",
  "source_quote": "Treatment with anti-obesity drugs (e.g. sibutramine, orlistat) 3 months prior to informed consent or any other treatment at the time of screening (i.e. surgery, aggressive diet regimen, etc.) leading to unstable body weight",
  "predicate": {
    "type": "unsupported",
